// First Unique Character - Find the first non-repeating character
var table = AnimatedHashTable<String, Int>()
let text = ["l", "e", "e", "t", "c", "o", "d", "e"]

func firstUniqChar(_ chars: [String], t: inout AnimatedHashTable<String, Int>) -> Int {
    for char in chars {
        let count = t.get(char) ?? 0
        t.put(char, count + 1)
    }
    for i in 0..<chars.count {
        if t.get(chars[i]) == 1 {
            return i
        }
    }
    return -1
}

let firstUniqueIndex = firstUniqChar(text, t: &table)
